import openpyxl
p='/tmp/llm_rollout_bl_9yhra/3_36097_answer_template_2723_input.xlsx'
wb=openpyxl.load_workbook(p, data_only=False)
ws=wb.active
# Count formulas: should be 14 and unchanged
formulas=[]
for row in ws.iter_rows(min_row=1, max_row=7, max_col=8):
    for c in row:
        if isinstance(c.value, str) and c.value.startswith('='):
            formulas.append((c.coordinate, c.value))
print('Formula count:', len(formulas))
for f in formulas: print(f)
# Count data cells filled in B2:G6
filled=0
for row in ws.iter_rows(min_row=2, max_row=6, min_col=2, max_col=7):
    for c in row:
        if c.value is not None:
            filled+=1
print('Data cells filled in B2:G6:', filled)
